import io, zipfile
import xml.etree.ElementTree as ET
NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
W = '{' + NS + '}'

def run(text, bold=False):
    props = '<w:rPr><w:b/></w:rPr>' if bold else ''
    return '<w:r>%s<w:t xml:space="preserve">%s</w:t></w:r>' % (props, text)

def make_docx(paragraphs):
    body = ''.join('<w:p>%s</w:p>' % ''.join(run(t, b) for t, b in runs) for runs in paragraphs)
    xml = '<w:document xmlns:w="%s"><w:body>%s</w:body></w:document>' % (NS, body)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, 'w') as z:
        z.writestr('word/document.xml', xml)
    return buf.getvalue()

data = make_docx([[('Invoice ', False), ('2026', True)],
                  [('Pay within ', False), ('30 days', True), (' of receipt.', False)]])
root = ET.fromstring(zipfile.ZipFile(io.BytesIO(data)).read('word/document.xml'))
paragraphs = root.findall('.//' + W + 'p')
print(len(paragraphs), 'paragraphs')
for p in paragraphs:
    runs = p.findall(W + 'r')
    marks = [(r.find(W + 't').text, r.find(W + 'rPr/' + W + 'b') is not None)
             for r in runs]
    print(len(runs), 'runs:', marks)

def get_text(paragraphs, joiner='\n'):
    return joiner.join(''.join(t.text for t in p.iter(W + 't')) for p in paragraphs)

print(repr(get_text(paragraphs)))
print(repr(get_text(paragraphs, '\n\n')))

def pages_copied(selection):
    if isinstance(selection, tuple):
        return list(range(*selection))
    return list(selection)

print(pages_copied((0, 5)), pages_copied((0, 5, 2)), pages_copied([0, 5]))
